'use strict';
const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Builds a Source (src/source.ts contract) that records open/read/close calls.
function makeSource(queue, hooks = {}) {
  const state = { opens: 0, reads: 0, closes: 0 };
  return {
    state,
    source: {
      async open() {
        state.opens += 1;
        if (hooks.openError) throw hooks.openError;
        return {
          async read() {
            state.reads += 1;
            if (hooks.readError) throw hooks.readError;
            return queue.length > 0 ? queue.shift() : null;
          },
          async close() {
            state.closes += 1;
            if (hooks.closeError) throw hooks.closeError;
          },
        };
      },
    },
  };
}

async function main() {
  // Returning an unopened generator must not open or close anything.
  {
    const { state, source } = makeSource(['a']);
    const gen = new EventService(source).stream();
    assert.deepEqual(await gen.return(), { value: undefined, done: true });
    assert.equal(state.opens, 0);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);
  }

  // Opening is deferred until first iteration; one read per next(), in order.
  {
    const { state, source } = makeSource(['a', 'b', null]);
    const gen = new EventService(source).stream();
    assert.equal(state.opens, 0);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);

    assert.deepEqual(await gen.next(), { value: 'A', done: false });
    assert.equal(state.opens, 1);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 0);

    assert.deepEqual(await gen.next(), { value: 'B', done: false });
    assert.equal(state.reads, 2);
    assert.equal(state.closes, 0);

    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(state.reads, 3);
    assert.equal(state.closes, 1);
  }

  // Normal exhaustion via for await closes exactly once and preserves order.
  {
    const { state, source } = makeSource(['a', 'b', null]);
    const seen = [];
    for await (const value of new EventService(source).stream()) seen.push(value);
    assert.deepEqual(seen, ['A', 'B']);
    assert.equal(state.opens, 1);
    assert.equal(state.reads, 3);
    assert.equal(state.closes, 1);
  }

  // Consumer break closes exactly once and does not read ahead.
  {
    const { state, source } = makeSource(['a', 'b', 'c']);
    for await (const value of new EventService(source).stream()) {
      assert.equal(value, 'A');
      break;
    }
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Consumer return closes exactly once; later returns do not close again.
  {
    const { state, source } = makeSource(['a', 'b']);
    const gen = new EventService(source).stream();
    assert.equal((await gen.next()).value, 'A');
    assert.deepEqual(await gen.return(), { value: undefined, done: true });
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
    assert.deepEqual(await gen.return(), { value: undefined, done: true });
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Source read failure closes once and preserves the read error.
  {
    const readError = new Error('read failed');
    const { state, source } = makeSource([], { readError });
    await assert.rejects(new EventService(source).stream().next(), (error) => error === readError);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Mapper failure closes once and preserves the mapper error.
  {
    const mapperError = new Error('mapper failed');
    const { state, source } = makeSource(['a', 'b']);
    const service = new EventService(source, () => { throw mapperError; });
    await assert.rejects(service.stream().next(), (error) => error === mapperError);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Consumer-injected throw closes once and preserves the injected error.
  {
    const injected = new Error('injected');
    const { state, source } = makeSource(['a', 'b']);
    const gen = new EventService(source).stream();
    assert.equal((await gen.next()).value, 'A');
    await assert.rejects(gen.throw(injected), (error) => error === injected);
    assert.equal(state.reads, 1);
    assert.equal(state.closes, 1);
  }

  // Close failure on normal exhaustion propagates the close error.
  {
    const closeError = new Error('close failed');
    const { state, source } = makeSource([null], { closeError });
    await assert.rejects(new EventService(source).stream().next(), (error) => error === closeError);
    assert.equal(state.closes, 1);
  }

  // Close failure on consumer return propagates the close error.
  {
    const closeError = new Error('close failed');
    const { state, source } = makeSource(['a'], { closeError });
    const gen = new EventService(source).stream();
    assert.equal((await gen.next()).value, 'A');
    await assert.rejects(gen.return(), (error) => error === closeError);
    assert.equal(state.closes, 1);
  }

  // Close failure alongside a read failure preserves the read error.
  {
    const readError = new Error('read failed');
    const closeError = new Error('close failed');
    const { state, source } = makeSource([], { readError, closeError });
    await assert.rejects(new EventService(source).stream().next(), (error) => error === readError);
    assert.equal(state.closes, 1);
  }

  // Close failure alongside a mapper failure preserves the mapper error.
  {
    const mapperError = new Error('mapper failed');
    const closeError = new Error('close failed');
    const { state, source } = makeSource(['a'], { closeError });
    const service = new EventService(source, () => { throw mapperError; });
    await assert.rejects(service.stream().next(), (error) => error === mapperError);
    assert.equal(state.closes, 1);
  }

  // Close failure alongside an injected throw preserves the injected error.
  {
    const injected = new Error('injected');
    const closeError = new Error('close failed');
    const { state, source } = makeSource(['a'], { closeError });
    const gen = new EventService(source).stream();
    assert.equal((await gen.next()).value, 'A');
    await assert.rejects(gen.throw(injected), (error) => error === injected);
    assert.equal(state.closes, 1);
  }

  // Open failure propagates and never attempts to read or close.
  {
    const openError = new Error('open failed');
    const { state, source } = makeSource([], { openError });
    await assert.rejects(new EventService(source).stream().next(), (error) => error === openError);
    assert.equal(state.opens, 1);
    assert.equal(state.reads, 0);
    assert.equal(state.closes, 0);
  }

  // A completed stream never reads or closes again on later next().
  {
    const { state, source } = makeSource(['a', null]);
    const gen = new EventService(source).stream();
    assert.equal((await gen.next()).value, 'A');
    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(state.reads, 2);
    assert.equal(state.closes, 1);
    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(state.reads, 2);
    assert.equal(state.closes, 1);
  }
}

module.exports = main();
